const e=[{id:1,icon:"Flame",accent:"#dc2626",title:"Fire and its dangers",subtitle:"Protecting yourself from fire",grades:"1-2",ages:"6-8",summary:"Fire is a chemical reaction between three things: heat, fuel and oxygen. If one of them is taken away, the fire goes out.",blocks:[{heading:"The fire triangle",body:"Fire is made of three things: heat, fuel and oxygen.",image:"media/images/fire_triangle.png"},{heading:"Stop, Drop and Roll",body:"If your clothes catch fire, do not run! Stop, drop to the ground, cover your face with your hands and roll on the ground until the fire goes out.",image:"media/images/stop_drop_roll.png"},{heading:"Getting out safely",body:"Know the ways out. If there is smoke, get low and crawl on your hands and knees. Outside, wait at the assembly point and tell an adult.",image:"media/images/fire_exit.png"}],examples:["Test the smoke alarm every month with an adult.","Make a home escape plan with your family.","Learn the number 115 by heart.","Know your school's assembly point."],tips:["Do not play with matches or lighters.","If you see smoke, get low.","Always know two ways out."],warnings:["During a fire, never hide under the bed or in a wardrobe! The Civil Defense team will not be able to find you. Get out and tell an adult."],realCase:"At a school, a pupil saw smoke. He told the teacher right away, and everyone got out safely.",video:"media/videos/lesson_fire.mp4",game:{instruction:"Which of these are the right things to do during a fire?",items:[{text:"Stop, drop and roll",emoji:"🔄",correct:!0},{text:"Run when your clothes catch fire",emoji:"🏃",correct:!1},{text:"Stay low under the smoke",emoji:"🐢",correct:!0},{text:"Take the elevator",emoji:"🛗",correct:!1}]},activity:{prompt:"You are at home and you see a fire in the kitchen. What will you do?",image:"media/images/activity_fire.png",options:[{text:"I leave the house right away, tell an adult and we call 115",correct:!0,feedback:"Getting out right away, telling an adult and calling 115 is the safe thing to do."},{text:"I try to put the fire out with water",correct:!1,feedback:"Children do not put out fires, and water on burning oil is dangerous; get out and tell an adult."},{text:"I hide",correct:!1,feedback:"If you hide, the Civil Defense team cannot find you; get out and tell an adult."},{text:"I stay there and watch",correct:!1,feedback:"Staying near a fire is not safe; leave the house right away and tell an adult."}]},quiz:[{question:"If your clothes catch fire, what will you do?",options:[{text:"I run fast to find water and put the fire out",correct:!1,feedback:"Running makes the fire bigger!"},{text:"I stop, drop to the ground and roll",correct:!0,feedback:"Well done!"},{text:"I cry and wait for someone to come",correct:!1,feedback:"Crying does not put the fire out."}]},{question:"What are the three elements of fire?",options:[{text:"Heat, fuel, oxygen",correct:!0,feedback:"Heat, fuel and oxygen together make the fire triangle."},{text:"Water, wind, heat",correct:!1,feedback:"No. Fire needs heat, fuel and oxygen, and water is not one of them. Never pour water on burning oil or on electrical things."},{text:"Smoke, water, snow",correct:!1,feedback:"Smoke, water and snow do not make fire; fire needs heat, fuel and oxygen."}],explanation:"Fire is made of three things: heat, fuel and oxygen. If one of them is taken away, the fire goes out."},{question:"What is the Civil Defense number?",options:[{text:"115",correct:!0,feedback:"115 is the Civil Defense number, and you have learned it well!"},{text:"122",correct:!1,feedback:"No, 122 is the ambulance number."},{text:"9-1-1",correct:!1,feedback:"No, that is the number in America, not in Kurdistan."}],explanation:"In Kurdistan, 115 is the Civil Defense number. Learn it by heart!"}]},{id:2,icon:"Activity",accent:"#ea580c",title:"Earthquakes",subtitle:"Staying safe during an earthquake",grades:"1-2",ages:"6-8",summary:"An earthquake is a natural event. We cannot stop it, but we can protect ourselves.",blocks:[{heading:"Drop, Cover, Hold On",body:"Drop to your knees, take cover under a sturdy table and hold on tightly to the table leg until the shaking stops. If there is no table, kneel next to a wall away from windows and protect your head and neck with your hands.",image:"media/images/drop_cover_hold.png"},{heading:"Away from glass",body:"Glass can break and hurt you. Keep away from windows, mirrors and heavy things that could fall.",image:"media/images/earthquake_glass.png"},{heading:"After the shaking",body:"When the shaking has stopped, leave calmly by the stairs with your teacher. Do not use the elevator. Stay alert, because smaller shakes (aftershocks) may follow.",image:"media/images/after_earthquake.png"}],examples:["Take cover under a sturdy table.","Keep away from windows.","Listen to your teacher.","Leave calmly after the shaking stops."],tips:["Know the safe places in your classroom and at home.","Get water and an emergency bag ready with your family.","Learn the number 115 by heart."],warnings:["During an earthquake, do not run, do not stand in a doorway and never use the elevator!"],realCase:"During an earthquake, a pupil took cover under a table and held on to the table leg. He stayed safe!",video:"media/videos/lesson_earthquake.mp4",game:{instruction:"Which are the right things to do during an earthquake?",items:[{text:"Take cover under a table",emoji:"🪑",correct:!0},{text:"Take the elevator",emoji:"🛗",correct:!1},{text:"Protect your head",emoji:"🛡️",correct:!0},{text:"Stand by the window",emoji:"🪟",correct:!1}]},activity:{prompt:"You are in class and the ground is shaking. Your teacher is not there. What will you do?",image:"media/images/activity_eq.png",options:[{text:"I get under my desk, protect my head and hold on to the desk leg",correct:!0,feedback:"This is Drop, Cover, Hold On, and it protects you from falling things."},{text:"I run outside",correct:!1,feedback:"You could fall and get hurt if you run; drop, cover and hold on."},{text:"I go to the window",correct:!1,feedback:"Window glass can break and hurt you; keep away from windows."},{text:"I cry",correct:!1,feedback:"It is okay to be scared, but crying does not protect you; get under your desk and hold on to its leg."}]},quiz:[{question:"During an earthquake, what is the first thing to do?",options:[{text:"Drop, Cover, Hold On",correct:!0,feedback:"Drop, Cover, Hold On protects you from things that fall during the shaking."},{text:"Run outside as fast as you can",correct:!1,feedback:"No, you could fall and get hurt."},{text:"Stand still in the middle of the room",correct:!1,feedback:"No, things could fall on you."}],explanation:"During an earthquake: drop to your knees, take cover under a sturdy table and hold on to its leg until the shaking stops."},{question:"What should we keep away from?",options:[{text:"Windows and glass",correct:!0,feedback:"Glass breaks and can hurt you, so stay away from windows!"},{text:"A sturdy table",correct:!1,feedback:"No, a sturdy table is a safe place."},{text:"The floor of the room",correct:!1,feedback:"No, during an earthquake you should drop to the floor."}],explanation:"Glass can break and hurt you. Keep away from windows, mirrors and heavy things that could fall."},{question:"The shaking has stopped. How do you leave the building?",options:[{text:"Calmly by the stairs, with your teacher",correct:!0,feedback:"Leaving calmly by the stairs with your teacher is the safe way out after the shaking."},{text:"Quickly in the elevator, with your friends",correct:!1,feedback:"No, do not use the elevator. Leave calmly by the stairs with your teacher."},{text:"Running alone, before everyone else",correct:!1,feedback:"If you run, you could fall and get hurt; leave calmly with your teacher and stay alert, because smaller shakes may follow."}],explanation:"When the shaking has stopped, leave calmly by the stairs with your teacher. Do not use the elevator, and stay alert, because smaller shakes may follow."}]},{id:3,icon:"Zap",accent:"#ca8a04",title:"Electricity and its dangers",subtitle:"Electrical safety",grades:"2-3",ages:"7-9",summary:"Electricity is an invisible and powerful force. If we are not careful, it can injure us or even kill us.",blocks:[{heading:"Electrical sockets",body:"Do not put your fingers or anything made of metal into electrical sockets.",image:"media/images/electric_outlet.png"},{heading:"Water and electricity are dangerous together",body:"Do not touch electrical appliances or switches with wet hands.",image:"media/images/water_electric.png"},{heading:"Broken wires",body:"Do not go near broken or fallen wires, and do not touch them. Tell an adult right away.",image:"media/images/broken_wire.png"}],examples:["Do not touch switches with wet hands.","If you see a broken wire, tell an adult.","Do not use broken appliances.","Only touch switches with dry hands."],tips:["Switch off electrical appliances when you are not using them.","Do not use electrical appliances in the bathroom or near water.","Do not touch wires."],warnings:["Do not touch broken wires lying on the ground! Electricity can kill!"],realCase:"A pupil saw a broken wire in the school yard and did not go near it. He told the teacher right away, and all the pupils stayed safe!",video:"media/videos/lesson_electricity.mp4",game:{instruction:"Which of these are dangerous?",items:[{text:"Wet hands and a light switch",emoji:"💧",correct:!0},{text:"A book",emoji:"📚",correct:!1},{text:"A broken wire",emoji:"⚡",correct:!0},{text:"Shoes",emoji:"👟",correct:!1}]},activity:{prompt:"Your hands are wet and you want to switch on the fan. What will you do?",image:"media/images/activity_elec.png",options:[{text:"First I dry my hands",correct:!0,feedback:"Dry hands are safe, because water carries electricity."},{text:"I switch it on with wet hands",correct:!1,feedback:"Water carries electricity, so wet hands on a switch are dangerous; dry them first."},{text:"It does not matter",correct:!1,feedback:"It does matter: water and electricity together are dangerous, so dry your hands first."},{text:"I take it into the bathroom and use it there",correct:!1,feedback:"Water carries electricity, so do not use electrical appliances in the bathroom or near water."}]},quiz:[{question:"Why are wet hands and electricity dangerous together?",options:[{text:"Water carries electricity",correct:!0,feedback:"Water carries electricity, so dry your hands first, then touch the switch."},{text:"Your wet hands start to itch",correct:!1,feedback:"The danger is not itching: water carries electricity, and electricity can injure you."},{text:"It does not matter",correct:!1,feedback:"It is dangerous!"}],explanation:"Water carries electricity. That is why you only touch switches and electrical appliances with dry hands."},{question:"If you see a broken wire, what will you do?",options:[{text:"I do not go near it, and I tell an adult",correct:!0,feedback:"Staying away keeps you safe, and telling an adult keeps everyone safe."},{text:"I pick it up and carry it out of the way",correct:!1,feedback:"No! A broken wire can still have electricity in it. Stay away and tell an adult."},{text:"I touch it to see if it still works",correct:!1,feedback:"No! Electricity can kill."}],explanation:"Electricity can kill. Do not go near broken or fallen wires, do not touch them, and tell an adult right away."},{question:"A child wants to push something made of metal into an electrical socket. Is that safe?",options:[{text:"No, metal must never go in a socket",correct:!0,feedback:"Right: never put your fingers or anything made of metal into a socket, because electricity can injure or kill."},{text:"Yes, if the child's hands are dry",correct:!1,feedback:"Dry hands are for switches; nothing made of metal goes into a socket, even with dry hands."},{text:"Yes, if all the lights in the room are off",correct:!1,feedback:"Switching off the lights does not make a socket safe; never put anything made of metal into a socket."}],explanation:"Do not put your fingers or anything made of metal into electrical sockets. Electricity is a powerful force that can injure or even kill."}]},{id:4,icon:"TrafficCone",accent:"#2563eb",title:"Road safety",subtitle:"Streets and traffic",grades:"1-2",ages:"6-8",summary:"The street is a very dangerous place for children. Let us learn how to cross the road safely.",blocks:[{heading:"Cross at the crossing",body:"Always cross the road on the white crossing lines (the crosswalk).",image:"media/images/crosswalk.png"},{heading:"Look left and right",body:"Stop at the edge of the road. Look left, then right, then left again. When the road is clear, cross calmly.",image:"media/images/look_both.png"},{heading:"The language of traffic lights",body:"Look at the pedestrian light, the one with a little person. Red person = wait on the sidewalk. Green person = look left, right and left again, then walk straight across with a grown-up. The big lights are for drivers: when they are green, cars are moving.",image:"media/images/traffic_lights.png"}],examples:["Watch the traffic lights.","Look left and right.","Cross on the crossing lines.","Hold an adult's hand."],tips:["Take your headphones off when you are on the street.","Hold an adult's hand when you cross.","Be extra careful on streets with no traffic lights."],warnings:["Never cross the road from between parked cars!"],realCase:"A pupil taught her friends how to cross the road safely. Now they all get to school safely!",video:"media/videos/lesson_road.mp4",game:{instruction:"On the pedestrian light, what does the green person mean?",items:[{text:"Stop",emoji:"🔴",correct:!1},{text:"Look, then cross with a grown-up",emoji:"🟢",correct:!0},{text:"Run fast",emoji:"🏃",correct:!1},{text:"Cross between the cars",emoji:"🚗",correct:!1}]},activity:{prompt:"The pedestrian light shows the red person and cars are coming. What will you do?",image:"media/images/activity_road.png",options:[{text:"I wait on the sidewalk until the green person shows, look left, right and left again, and cross with a grown-up",correct:!0,feedback:"Waiting for the green person and looking again keep you safe from the cars."},{text:"I run across quickly",correct:!1,feedback:"Cars are coming and the light is red; running across is not safe, so wait on the sidewalk."},{text:"I cross without looking",correct:!1,feedback:"Without looking, you cannot see the cars; wait for the green person and look left, right and left again."},{text:"I cross between the cars",correct:!1,feedback:"Crossing between cars is not safe; cross on the white crossing lines when the green person shows."}]},quiz:[{question:"What does the red light mean?",options:[{text:"Stop",correct:!0,feedback:"Red means stop, so you wait safely on the sidewalk."},{text:"Go",correct:!1,feedback:"Red is not for going: wait on the sidewalk until the green person shows."},{text:"Run fast",correct:!1,feedback:"Running on red is not safe; stop and wait on the sidewalk."}],explanation:"Red means stop: when the red person shows, wait on the sidewalk. When the green person shows, look left, right and left again, then cross with a grown-up."},{question:"What will you do before you cross the road?",options:[{text:"I look left and right",correct:!0,feedback:"Looking left, right and left again shows you whether the road is clear."},{text:"I run across very fast",correct:!1,feedback:"Running into the road is not safe; first stop at the edge and look left and right."},{text:"I do nothing",correct:!1,feedback:"Before crossing, always stop and look left and right, so you know the road is clear."}],explanation:"Stop at the edge of the road and look left, then right, then left again. Cross calmly only when the road is clear."},{question:"Where do you cross the road?",options:[{text:"On the white crossing lines (the crosswalk)",correct:!0,feedback:"The white crossing lines (the crosswalk) are the place to cross; first look left, right and left again."},{text:"From between two parked cars",correct:!1,feedback:"Never cross from between parked cars; always cross on the white crossing lines."},{text:"Wherever the road looks shortest and quickest",correct:!1,feedback:"Do not cross just anywhere; always cross on the white crossing lines (the crosswalk)."}],explanation:"Always cross the road on the white crossing lines (the crosswalk), and never cross from between parked cars."}]},{id:5,icon:"HeartPulse",accent:"#16a34a",title:"First aid",subtitle:"The basics of first aid",grades:"3-4",ages:"8-10",summary:"First aid is the help given right away to someone who is injured or ill, before the ambulance arrives. If someone is badly injured or seriously ill, tell an adult so they can call 122 (Ambulance).",blocks:[{heading:"Small wounds",body:"Wash the wound with clean water, put a clean dressing on it and tell an adult.",image:"media/images/first_aid_wound.png"},{heading:"Burns",body:"Hold the burned area under cool running water for 20 minutes. Do not put ice, butter or toothpaste on it. Tell an adult; for a serious burn, they will call 122.",image:"media/images/first_aid_burn.png"},{heading:"The first aid kit",body:"Every home and every school should have a first aid kit.",image:"media/images/first_aid_kit.png"}],examples:["Use a clean dressing.","20 minutes of cool water for a burn.","Ambulance = 122; tell an adult.","Know where the first aid kit is kept."],tips:["Wash your hands before putting on a dressing.","Do not touch the inside of a wound.","Speak calmly to the injured person."],warnings:["Never give anyone medicine yourself! Only give simple help and tell adults."],realCase:"A pupil fell over in the school yard and hurt his knee. His friend told the teacher right away, and the teacher cleaned the wound and put a dressing on it. He was soon better!",video:"media/videos/lesson_firstaid.mp4",game:{instruction:"What is inside a first aid kit?",items:[{text:"Dressings",emoji:"🩹",correct:!0},{text:"Candy",emoji:"🍬",correct:!1},{text:"Cotton",emoji:"🩹",correct:!0},{text:"A doll",emoji:"🧸",correct:!1}]},activity:{prompt:"Your friend has fallen over and his hand is bleeding. What will you do?",image:"media/images/activity_fa.png",options:[{text:"I press on the wound with a clean cloth and tell the teacher right away",correct:!0,feedback:"A clean cloth on the wound helps, and telling the teacher means your friend gets help fast."},{text:"I do nothing",correct:!1,feedback:"Your friend needs help; press on the wound with a clean cloth and tell the teacher right away."},{text:"I run away",correct:!1,feedback:"Running away leaves your friend without help; tell the teacher right away."},{text:"I carry on playing",correct:!1,feedback:"Your friend is hurt and needs help now; stop playing and tell the teacher right away."}]},quiz:[{question:"What do we do for a small burn?",options:[{text:"Cool running water for 20 minutes",correct:!0,feedback:"Cool running water for 20 minutes cools the burn; then tell an adult."},{text:"Some spices from the kitchen cupboard",correct:!1,feedback:"For a burn, use cool running water for 20 minutes, not spices."},{text:"Butter, so the burn hurts less",correct:!1,feedback:"No! Butter makes a burn worse."}],explanation:"Hold a burn under cool running water for 20 minutes. Do not put ice, butter or toothpaste on it, and tell an adult."},{question:"Before putting on a dressing, what do we do with our hands?",options:[{text:"We wash them",correct:!0,feedback:"Clean hands help keep the wound clean."},{text:"We do nothing",correct:!1,feedback:"Wash your hands first, so the wound stays clean."},{text:"We wipe them on our clothes",correct:!1,feedback:"Wiping your hands on clothes is not washing them; wash your hands before putting on a dressing."}],explanation:"Wash your hands before putting on a dressing, so the wound stays clean. Do not touch the inside of the wound."},{question:"Your friend feels ill. Can you give him medicine yourself?",options:[{text:"No, I tell an adult",correct:!0,feedback:"Never give anyone medicine yourself; give only simple help and tell an adult."},{text:"Yes, a medicine from home",correct:!1,feedback:"Never give anyone medicine yourself, not even one from home; tell an adult."},{text:"Yes, if he asks",correct:!1,feedback:"Even if he asks, never give medicine yourself; tell an adult."}],explanation:"Never give anyone medicine yourself! Only give simple help and tell adults."}]},{id:6,icon:"Waves",accent:"#0891b2",title:"Floods and water safety",subtitle:"The danger of floods",grades:"2-3",ages:"7-9",summary:"A flood happens when a lot of rain falls and water builds up. Floods are dangerous and can sweep away things and people.",blocks:[{heading:"Stay away from flood water",body:"Never go into flood water. Just 15 centimeters of moving water can knock a person over, and 30 centimeters can carry a car away.",image:"media/images/flood_danger.png"},{heading:"Go to high ground",body:"If a flood comes, go to high ground with adults right away.",image:"media/images/flood_high.png"},{heading:"Weather warnings",body:"Listen to weather warnings and to what adults tell you. Be prepared.",image:"media/images/flood_warning.png"}],examples:["If your home is on high ground, stay at home.","Go to high ground.","Listen to the warnings.","Do not play in flood water."],tips:["When a flood is coming, do not go to low places or valleys.","Tell adults.","Be prepared before the rainy season."],warnings:["Never walk or swim in flood water! Flood water is stronger than you."],realCase:"During very heavy rain, water flooded into the street. A father took his children up to the third floor of the building, and they all stayed safe!",video:"media/videos/lesson_flood.mp4",game:{instruction:"What do we do during a flood?",items:[{text:"Go to high ground",emoji:"⬆️",correct:!0},{text:"Swim in the water",emoji:"🏊",correct:!1},{text:"Stay on the top floor at home",emoji:"🏠",correct:!0},{text:"Drive through the water in a car",emoji:"🚗",correct:!1}]},activity:{prompt:"It is raining heavily and water is building up on the street. What will you do?",image:"media/images/activity_flood.png",options:[{text:"I go to high ground with adults",correct:!0,feedback:"Going to high ground with adults keeps you away from the flood water."},{text:"I walk into the water",correct:!1,feedback:"Just 15 centimeters of moving water can knock a person over; never walk into flood water."},{text:"I stand near the water and watch",correct:!1,feedback:"A flood can sweep people away, so do not stay near the water; go to high ground with adults."},{text:"I go swimming",correct:!1,feedback:"Flood water is stronger than you, even if you can swim; go to high ground with adults."}]},quiz:[{question:"If a flood comes, where will we go?",options:[{text:"To high ground",correct:!0,feedback:"High ground keeps you away from the flood water."},{text:"To low places",correct:!1,feedback:"Low places and valleys are not safe in a flood; go to high ground with adults."},{text:"Into the water",correct:!1,feedback:"Flood water is stronger than you and can sweep you away; never go into it."}],explanation:"Flood water is stronger than you: just 15 centimeters of moving water can knock a person over. Go to high ground with adults right away."},{question:"You can swim well. Can you swim in flood water?",options:[{text:"No, it is stronger than you",correct:!0,feedback:"Flood water is stronger than you, even if you can swim; never go into it."},{text:"Yes, if the water looks calm",correct:!1,feedback:"Never swim in flood water: it is stronger than you and can sweep people away."},{text:"Yes, if a friend swims with you",correct:!1,feedback:"A friend does not make flood water safe, because flood water is stronger than you; go to high ground with adults."}],explanation:"Never walk or swim in flood water! Flood water is stronger than you, even if you can swim, and it can sweep people away."},{question:"A flood is coming and your home is on high ground. What do you do?",options:[{text:"I stay at home with adults",correct:!0,feedback:"If your home is on high ground, staying at home keeps you away from the flood water."},{text:"I go out to look at the water",correct:!1,feedback:"Do not go near flood water; if your home is on high ground, stay at home."},{text:"I go down to the valley",correct:!1,feedback:"Valleys and low places are not safe when a flood is coming; stay in your home on high ground."}],explanation:"If your home is on high ground, stay at home. When a flood is coming, do not go to low places or valleys, and never go into flood water."}]},{id:7,icon:"Wind",accent:"#059669",title:"Gas leaks",subtitle:"Recognizing the danger of gas",grades:"3-4",ages:"8-10",summary:"Gas is used for cooking and for heating the home. A gas leak is dangerous and can cause a fire or an explosion.",blocks:[{heading:"The smell of gas",body:"If you smell something like rotten eggs, gas may be leaking!",image:"media/images/gas_smell.png"},{heading:"Open the windows",body:"If you can do it easily on your way out, open the windows and doors to let the gas out. Do not stay inside to do it: leave the house right away.",image:"media/images/gas_ventilate.png"},{heading:"Do not light a flame!",body:"Do not strike a match or use a lighter, do not touch light switches and do not use a phone inside the house. Even a tiny spark can cause an explosion.",image:"media/images/gas_no_fire.png"}],examples:["A smell of rotten eggs = gas.","Open the windows.","Do not light a flame!","Get out and call 115 from outside."],tips:["Children never turn off the gas: get out and tell an adult.","Adults should check the gas pipes regularly.","Call 115 from outside the house."],warnings:["When you smell gas, do not touch light switches and do not light a flame!"],realCase:"A child smelled gas in the kitchen. He did not touch the switches and told his father. Everyone left the house, his father called 115 from outside and everyone stayed safe!",video:"media/videos/lesson_gas.mp4",game:{instruction:"When there is a smell of gas, which things must we NOT do?",items:[{text:"Strike a match",emoji:"🔥",correct:!0},{text:"Open the window",emoji:"🪟",correct:!1},{text:"Turn on a light switch",emoji:"💡",correct:!0},{text:"Leave the house",emoji:"🚶",correct:!1}]},activity:{prompt:"There is a smell like rotten eggs at home. What will you do?",image:"media/images/activity_gas.png",options:[{text:"I do not touch the switches, I go outside, opening a window on my way if it is easy, and I tell an adult",correct:!0,feedback:"Not touching switches means no spark, and getting out and telling an adult keeps everyone safe."},{text:"I turn on the light so I can see better",correct:!1,feedback:"A light switch can make a tiny spark, and a spark can cause an explosion; do not touch switches."},{text:"I stay at home",correct:!1,feedback:"Gas can cause a fire or an explosion, so leave the house right away and tell an adult."},{text:"I strike a match",correct:!1,feedback:"A match can cause an explosion; never light a flame, get out and tell an adult."}]},quiz:[{question:"What does gas smell like?",options:[{text:"Rotten eggs",correct:!0,feedback:"A smell like rotten eggs warns you that gas may be leaking."},{text:"Flowers",correct:!1,feedback:"Gas does not smell like flowers; it smells like rotten eggs, so you notice it."},{text:"It has no smell",correct:!1,feedback:"No! A smell is added to gas so that we can notice it."}],explanation:"Gas smells like rotten eggs, because a smell is added so we can notice it. If you smell it, do not touch switches; get out and tell an adult."},{question:"Why must you not touch light switches when you smell gas?",options:[{text:"A tiny spark can cause an explosion",correct:!0,feedback:"A light switch can make a tiny spark, and a spark can cause an explosion."},{text:"The switch could break",correct:!1,feedback:"The danger is not a broken switch: a switch can make a tiny spark, and a spark can cause an explosion."},{text:"The light could make the smell stronger",correct:!1,feedback:"The danger is not the smell: a switch can make a tiny spark, and a spark can cause an explosion."}],explanation:"When you smell gas, do not touch light switches and do not light a flame. Even a tiny spark can cause an explosion."},{question:"You smell gas at home. Do you turn off the gas yourself?",options:[{text:"No, I get out and tell an adult",correct:!0,feedback:"Children never turn off the gas: get out, tell an adult and call 115 from outside the house."},{text:"Yes, I turn it off before I go out",correct:!1,feedback:"Children never turn off the gas, and they do not stay inside to do it: get out right away and tell an adult."},{text:"Yes, if no adult is at home",correct:!1,feedback:"Even with no adult at home, children never turn off the gas: get out and call 115 from outside the house."}],explanation:"Children never turn off the gas: get out and tell an adult. Call 115 from outside the house."}]},{id:8,icon:"PhoneCall",accent:"#e11d48",title:"Emergency number 115",subtitle:"Calling for help",grades:"1-2",ages:"6-8",summary:"115 is the Civil Defense number: for fires, rescue, earthquakes, floods and gas leaks. In an emergency, tell an adult so they can call 115. If there is no adult with you, call it yourself.",blocks:[{heading:"115 = Civil Defense",body:"Fire, earthquake, flood, explosion, collapsed buildings = call 115",image:"media/images/call_115.png"},{heading:"What do I say?",body:"First say where you are (the address or a place near you). Then say what has happened, how many people are there and whether anyone is injured, and your name. Do not hang up until they tell you to.",image:"media/images/what_to_say.png"},{heading:"It is not a game",body:"Never call 115 for fun! Someone else may need help.",image:"media/images/no_prank.png"}],examples:["115 = Civil Defense.","122 = Ambulance.","104 = Police.","Learn these numbers by heart."],tips:["Learn your home address by heart.","Speak calmly.","Listen to the instructions."],warnings:["Do not call 115 for fun! It is wrong and it is not allowed."],realCase:"A 10-year-old boy saw a fire near his home. He told his mother right away, his mother called 115 and the Civil Defense team came quickly!",video:"media/videos/lesson_115.mp4",game:{instruction:"Whose number is 115?",items:[{text:"Civil Defense",emoji:"🚒",correct:!0},{text:"Police",emoji:"👮",correct:!1},{text:"Ambulance",emoji:"🏥",correct:!1},{text:"The firefighting team",emoji:"🧯",correct:!0}]},activity:{prompt:"There is a fire near your home and there are no adults with you. What will you do?",image:"media/images/activity_115.png",options:[{text:"I move away from the fire, call 115 and give the address of the place",correct:!0,feedback:"Moving away from the fire keeps you safe, and giving the address helps the team get there quickly."},{text:"I put the fire out myself",correct:!1,feedback:"Children do not put out fires; move away, call 115 and give the address."},{text:"I stay close and watch",correct:!1,feedback:"Staying close to a fire is not safe; move away and call 115."},{text:"I go into the house",correct:!1,feedback:"Going into the house puts you in danger; stay outside, move away and call 115."}]},quiz:[{question:"What is 115 the number for?",options:[{text:"Civil Defense",correct:!0,feedback:"115 is for the Civil Defense: fires, rescue, earthquakes, floods and gas leaks."},{text:"Traffic police",correct:!1,feedback:"No, the police number is 104."},{text:"The ambulance",correct:!1,feedback:"No, the ambulance number is 122."}],explanation:"115 is the Civil Defense number, for fires, rescue, earthquakes, floods and gas leaks. The police number is 104 and the ambulance number is 122."},{question:"When you call 115, what do you say first?",options:[{text:"Where you are",correct:!0,feedback:"Saying the address first helps the team get there quickly."},{text:"Your name",correct:!1,feedback:"Your name comes at the end; first say where you are, so the team can get there quickly."},{text:"The name of your school",correct:!1,feedback:"The name of your school is not the first thing; first say where you are, so the team can get there quickly."}],explanation:"First say where you are (the address or a place near you). Then say what has happened, how many people are there and whether anyone is injured, and your name."},{question:"When you call 115, when can you hang up?",options:[{text:"Only when they tell you to",correct:!0,feedback:"Do not hang up until they tell you to; speak calmly and listen to the instructions."},{text:"As soon as you say the address",correct:!1,feedback:"Do not hang up yet: listen to the instructions and wait until they tell you to."},{text:"After you say your name",correct:!1,feedback:"Saying your name is not the end of the call; do not hang up until they tell you to."}],explanation:"Do not hang up until they tell you to. Speak calmly and listen to the instructions."}]},{id:9,icon:"DoorOpen",accent:"#7c3aed",title:"The escape plan",subtitle:"Getting out safely",grades:"3-4",ages:"8-10",summary:"An escape plan shows which way we can get out of a building safely and where we gather afterwards.",blocks:[{heading:"Ways out",body:"Every home and every school should have at least two ways out.",image:"media/images/exit_routes.png"},{heading:"The assembly point",body:"This is a safe place outside the building where everyone gathers, so that we know nobody has been left inside.",image:"media/images/assembly_point.png"},{heading:"Practice",body:"Practice getting out at home and at school once every three months.",image:"media/images/evacuation_drill.png"}],examples:["Know two ways out.","Know the assembly point.","Leave calmly.","Draw an escape map."],tips:["Draw a map of your home with your family.","Know the ways out so well that you could get out even in the dark.","Agree on an assembly point."],warnings:["During a fire or an earthquake, do not use the elevator; use the stairs!"],realCase:"The pupils of one school got out quickly and safely, because they had practiced beforehand!",video:"media/videos/lesson_evacuation.mp4",game:{instruction:"What will we use to get out safely?",items:[{text:"The stairs",emoji:"🪜",correct:!0},{text:"The elevator",emoji:"🛗",correct:!1},{text:"The emergency exit door",emoji:"🚪",correct:!0},{text:"The window",emoji:"🪟",correct:!1}]},activity:{prompt:"The alarm bell rings at school. What will you do?",image:"media/images/activity_evac.png",options:[{text:"I go calmly down the stairs to the assembly point",correct:!0,feedback:"Going calmly down the stairs is safe, and at the assembly point we know nobody is left inside."},{text:"I collect my things",correct:!1,feedback:"Getting out comes first, so leave your things and go calmly to the assembly point."},{text:"I take the elevator down",correct:!1,feedback:"The elevator may stop and you could get stuck inside; use the stairs."},{text:"I hide",correct:!1,feedback:"If you hide, nobody knows you are still inside; go to the assembly point."}]},quiz:[{question:"What will we use to get out of a building safely?",options:[{text:"The stairs",correct:!0,feedback:"The stairs are the safe way out, because the elevator may stop during a fire or an earthquake."},{text:"The elevator",correct:!1,feedback:"No! The elevator may stop and you could get stuck inside."},{text:"The window",correct:!1,feedback:"The safe way out is the stairs and the emergency exit door, not the window."}],explanation:"During a fire or an earthquake, use the stairs, not the elevator. The elevator may stop and you could get stuck inside."},{question:"Why does everyone gather at the assembly point?",options:[{text:"So we know nobody is left inside",correct:!0,feedback:"At the assembly point we can see that everyone is out and nobody has been left inside."},{text:"So everyone can watch what happens",correct:!1,feedback:"The assembly point is not for watching; it is where we check that nobody has been left inside."},{text:"So we can go back in for our bags",correct:!1,feedback:"Getting out comes first, so leave your things; at the assembly point we check that nobody is left inside."}],explanation:"The assembly point is a safe place outside the building where everyone gathers, so that we know nobody has been left inside."},{question:"How many ways out should every home and school have?",options:[{text:"At least two ways out",correct:!0,feedback:"Right: every home and every school should have at least two ways out, so there is always another way."},{text:"Only one, the main door",correct:!1,feedback:"One way out is not enough; every home and every school should have at least two ways out."},{text:"One, if it is big",correct:!1,feedback:"Even a big door is only one way out; there should be at least two ways out."}],explanation:"Every home and every school should have at least two ways out. Know them so well that you could get out even in the dark."}]},{id:10,icon:"FireExtinguisher",accent:"#d97706",title:"Firefighting equipment",subtitle:"Fire extinguishers and other equipment",grades:"4-5",ages:"9-11",summary:"A fire extinguisher is an important device for putting out small fires. Trained adults use it. The job of children is to get out, tell an adult and call 115.",blocks:[{heading:"Types of fire extinguisher",body:"There are powder, CO₂ and foam fire extinguishers. Each type is for certain kinds of fire.",image:"media/images/ext_types.png"},{heading:"PASS",body:`Adults decide whether to use a fire extinguisher. They use it only if the fire is very small and just starting, everyone has been warned and 115 has been called, the way out is behind them and free of smoke, and they are trained. If not, everyone gets out. Children never use a fire extinguisher: get out, tell an adult and call 115.

Adults use most fire extinguishers in these four steps: Pull (pull out the safety pin), Aim (aim the nozzle at the base of the fire), Squeeze (squeeze the handle), Sweep (sweep from side to side). Some special extinguishers have other steps, written on their label.`,image:"media/images/pass_method.png"},{heading:"Only for small fires",body:"A fire extinguisher is only for very small fires, and adults are the ones who use it. Children do not fight fires: get out, tell an adult and call 115!",image:"media/images/when_use_ext.png"}],examples:["P = Pull: pull out the pin.","A = Aim: aim at the base of the fire.","S = Squeeze: squeeze the handle.","S = Sweep: sweep from side to side."],tips:["Adults check the fire extinguisher by eye every month and have it serviced every year.","Know where the fire extinguishers are at your school.","During a fire, call for an adult."],warnings:["Children do not put out fires! Fire extinguishers are for adults. Get out, tell an adult and call 115."],realCase:"A small fire started in a classroom trash bin. The pupils left right away, and one of them told the teacher. The teacher, who was trained, made sure the alarm was raised and 115 was called. The fire was still very small and the way out was behind the teacher, so the teacher put it out with a fire extinguisher, using the PASS method.",video:"media/videos/lesson_extinguisher.mp4",game:{instruction:"What does PASS mean?",items:[{text:"The steps for using a fire extinguisher",emoji:"🧯",correct:!0},{text:"A type of fire",emoji:"🔥",correct:!1},{text:"An emergency number",emoji:"📞",correct:!1},{text:"Pull, aim at the base of the fire, squeeze, sweep",emoji:"✅",correct:!0}]},activity:{prompt:"There is a small fire in the classroom trash bin, and a fire extinguisher is near you. What will you do?",image:"media/images/activity_ext.png",options:[{text:"I leave the classroom right away, tell the teacher and we call 115",correct:!0,feedback:"Getting out, telling the teacher and calling 115 is the job of children, not putting out the fire."},{text:"I pour water on the fire",correct:!1,feedback:"Children do not put out fires, even small ones; leave the classroom and tell the teacher."},{text:"I use the fire extinguisher myself",correct:!1,feedback:"Fire extinguishers are for trained adults; children get out, tell an adult and call 115."},{text:"I stay in the classroom and watch",correct:!1,feedback:"Staying near a fire is not safe; leave the classroom right away and tell the teacher."}]},quiz:[{question:"What does the letter P in PASS mean?",options:[{text:"Pull: pull out the pin",correct:!0,feedback:"The first step is Pull: the adult pulls out the safety pin."},{text:"Push: push the handle down",correct:!1,feedback:"There is no push step: P means Pull, pulling out the safety pin."},{text:"Pour: pour it on the fire",correct:!1,feedback:"There is no pour step: P means Pull, pulling out the safety pin."}],explanation:"P stands for Pull: pull out the safety pin. Only trained adults use a fire extinguisher; children get out, tell an adult and call 115."},{question:"A small fire starts in the classroom. What is the job of children?",options:[{text:"Get out, tell an adult and call 115",correct:!0,feedback:"Children do not fight fires: their job is to get out, tell an adult and call 115."},{text:"Use the nearest fire extinguisher quickly",correct:!1,feedback:"Fire extinguishers are for trained adults; children get out, tell an adult and call 115."},{text:"Pour water on it",correct:!1,feedback:"Children do not put out fires, even small ones; get out, tell an adult and call 115."}],explanation:"Children never use a fire extinguisher and do not fight fires. The job of children is to get out, tell an adult and call 115."},{question:"A fire extinguisher is only for which fires?",options:[{text:"Very small fires that are just starting",correct:!0,feedback:"A fire extinguisher is only for very small fires that are just starting, and trained adults are the ones who use it."},{text:"Big fires that are spreading to other rooms",correct:!1,feedback:"A big fire is not for a fire extinguisher; everyone gets out and calls 115."},{text:"Any fire, as long as an adult uses it",correct:!1,feedback:"Adults use a fire extinguisher only if the fire is very small and just starting; if not, everyone gets out."}],explanation:"A fire extinguisher is only for very small fires that are just starting, and trained adults use it. If the fire is not very small, everyone gets out and calls 115."}]},{id:11,icon:"CloudFog",accent:"#475569",title:"Smoke and breathing",subtitle:"Breathing clean air",grades:"2-3",ages:"7-9",summary:"Smoke is very dangerous. It makes it hard to breathe and stops you from seeing well.",blocks:[{heading:"Smoke rises",body:"The clean air is near the floor. Get low and crawl on your hands and knees until you are out.",image:"media/images/smoke_rises.png"},{heading:"A wet cloth",body:"If you have a wet cloth with you, hold it over your mouth and nose. But do not stop to look for one; get out right away.",image:"media/images/wet_cloth.png"},{heading:"Check the door",body:"Before you open a door, test it with the back of your hand. If it is hot, do not open it; look for another way out. Once you are out, close the door behind you.",image:"media/images/check_door.png"}],examples:["Get low.","Hold a wet cloth over your mouth.","Test the door with the back of your hand.","Crawl on your hands and knees and get out."],tips:["Have smoke alarms fitted at home.","Know the way out, even in the dark.","The clean air is down low."],warnings:["In fires, smoke kills more people than the flames themselves! Do not use the elevator."],realCase:"During a house fire, a 10-year-old boy got down low and crawled out of the house. Knowing this can save your life too!",video:"media/videos/lesson_smoke.mp4",game:{instruction:"What do we do when there is smoke?",items:[{text:"Get low",emoji:"🐢",correct:!0},{text:"Walk standing up",emoji:"🧍",correct:!1},{text:"A wet cloth",emoji:"🧣",correct:!0},{text:"Open the window",emoji:"🪟",correct:!1}]},activity:{prompt:"The room has filled with smoke and you cannot see well. What will you do?",image:"media/images/activity_smoke.png",options:[{text:"I get low, put a cloth over my mouth and crawl out",correct:!0,feedback:"Down low the air is cleaner, and crawling gets you out of the smoke."},{text:"I walk out quickly, standing up",correct:!1,feedback:"Standing up puts your face in the smoke; get low and crawl out."},{text:"I open the window and stay there",correct:!1,feedback:"Staying in a smoky room is dangerous; get low and crawl out of the room."},{text:"I stay in the room",correct:!1,feedback:"Smoke makes it hard to breathe, so do not stay; get low and crawl out."}]},quiz:[{question:"Why do we get low when there is smoke?",options:[{text:"Smoke rises, and the clean air is down low",correct:!0,feedback:"Smoke rises and the clean air stays low, so getting low protects you."},{text:"Because it is fun",correct:!1,feedback:"Getting low is not a game: it keeps you in the clean air under the smoke."},{text:"So that we can see the door and the way out better",correct:!1,feedback:"We get low to breathe: smoke rises, and the clean air is near the floor."}],explanation:"Smoke rises, so the clean air is near the floor. Get low and crawl on your hands and knees until you are out."},{question:"How do you check a door before you open it?",options:[{text:"I touch it with the back of my hand",correct:!0,feedback:"Testing the door with the back of your hand tells you if it is hot; if it is hot, do not open it."},{text:"I open it a little and look outside first",correct:!1,feedback:"Do not open it first: test it with the back of your hand, and if it is hot, look for another way out."},{text:"I pull it open fast and look out",correct:!1,feedback:"Test the door with the back of your hand before you open it; if it is hot, do not open it."}],explanation:"Before you open a door, test it with the back of your hand. If it is hot, do not open it; look for another way out."},{question:"There is smoke and you have no wet cloth. What do you do?",options:[{text:"Get low and leave right away",correct:!0,feedback:"Do not stop to look for a cloth; get low and get out right away."},{text:"Look for a cloth first",correct:!1,feedback:"A wet cloth helps only if you already have one; do not stop to look for one, get out right away."},{text:"Wait until you find some water",correct:!1,feedback:"Do not wait in the smoke: smoke kills more people than the flames. Get low and get out right away."}],explanation:"If you have a wet cloth with you, hold it over your mouth and nose. But do not stop to look for one; get low and get out right away."}]},{id:12,icon:"FlaskConical",accent:"#9333ea",title:"Chemicals",subtitle:"The danger of unknown substances",grades:"4-5",ages:"9-11",summary:"There are chemicals in our homes, such as cleaning products and gasoline. These substances are dangerous if they are used the wrong way.",blocks:[{heading:"Do not drink or touch",body:"Do not drink or sniff an unknown liquid. It could be poison.",image:"media/images/chem_no_drink.png"},{heading:"Danger symbols",body:"Learn to recognize the danger symbols on bottles and boxes. If something has one of these symbols on it, do not touch it, and tell an adult.",image:"media/images/chem_signs.png"},{heading:"If it gets in your eyes",body:"Tell an adult right away. Rinse the eyes with clean running water for at least 15 minutes and call 122 (Ambulance).",image:"media/images/chem_eye.png"}],examples:["Do not drink unknown liquids.","Learn the danger symbols.","In your eyes: rinse with water.","Poisoning: call 122."],tips:["Adults should keep dangerous substances in a high place that is locked.","Learn the symbols.","Tell adults."],warnings:["Never mix cleaning products together! A poisonous gas could be made."],realCase:"A child found a colorful bottle in the kitchen and did not drink from it. She asked her mother and found out that it was a dangerous cleaning product.",video:"media/videos/lesson_chemical.mp4",game:{instruction:"Which of these are dangerous?",items:[{text:"Cleaning products",emoji:"🧴",correct:!0},{text:"Water",emoji:"💧",correct:!1},{text:"Gasoline",emoji:"⛽",correct:!0},{text:"Milk",emoji:"🥛",correct:!1}]},activity:{prompt:"You have found a bottle of an unknown liquid in the bathroom. What will you do?",image:"media/images/activity_chem.png",options:[{text:"I do not touch it, and I tell an adult",correct:!0,feedback:"An unknown liquid could be poison, so leaving it alone and telling an adult keeps you safe."},{text:"I smell it",correct:!1,feedback:"Even sniffing an unknown liquid is dangerous, because it could be poison; tell an adult."},{text:"I pour it on my hands",correct:!1,feedback:"An unknown liquid could be poison, so do not touch it; tell an adult."},{text:"I drink some of it",correct:!1,feedback:"An unknown liquid could be poison, so never drink it; tell an adult right away."}]},quiz:[{question:"If a chemical gets in your eyes, what will you do?",options:[{text:"I rinse them with clean water for at least 15 minutes and tell an adult",correct:!0,feedback:"Rinsing with clean water for at least 15 minutes washes the chemical away, and the adult can call 122."},{text:"I rub my eyes with my hands and keep them closed until it stops hurting",correct:!1,feedback:"No! That makes the damage worse."},{text:"I do nothing",correct:!1,feedback:"A chemical in the eyes needs help right away: rinse them with clean water and tell an adult."}],explanation:"Rinse your eyes with clean running water for at least 15 minutes and tell an adult right away, so they can call 122 (Ambulance)."},{question:"Why must you never mix cleaning products?",options:[{text:"A poisonous gas could be made",correct:!0,feedback:"Mixing cleaning products can make a poisonous gas, so never mix them."},{text:"They stop cleaning things well",correct:!1,feedback:"The danger is not poor cleaning: mixing cleaning products can make a poisonous gas."},{text:"They could lose their nice smell",correct:!1,feedback:"The danger is not the smell: mixing cleaning products can make a poisonous gas."}],explanation:"Never mix cleaning products together! A poisonous gas could be made."},{question:"A bottle has a danger symbol on it. What do you do?",options:[{text:"I do not touch it, and I tell an adult",correct:!0,feedback:"A danger symbol means the substance is dangerous, so leave it alone and tell an adult."},{text:"I open it carefully to see what is inside",correct:!1,feedback:"Do not open it; if something has a danger symbol on it, do not touch it, and tell an adult."},{text:"I smell it to find out what it is",correct:!1,feedback:"Do not drink or sniff an unknown liquid: it could be poison. Leave it and tell an adult."}],explanation:"If something has a danger symbol on it, do not touch it, and tell an adult. Do not drink or sniff an unknown liquid; it could be poison."}]},{id:13,icon:"AlertTriangle",accent:"#db2777",title:"Safety signs",subtitle:"Recognizing signs and symbols",grades:"1-2",ages:"6-8",summary:"Safety signs tell us things without words: there is danger here, this is not allowed or this is the way out.",blocks:[{heading:"Yellow triangle = danger",body:"A yellow triangle with a black picture means: be careful, there is danger!",image:"media/images/warning_sign.png"},{heading:"Red circle = not allowed",body:"A red circle with a red line across it means: do not do this!",image:"media/images/prohibit_sign.png"},{heading:"Green = safety",body:"A green square means safety, such as the emergency exit route or a first aid point.",image:"media/images/exit_sign.png"}],examples:["Yellow triangle = danger.","Red circle = not allowed.","Green square = safety.","Blue circle = an instruction (you must do it)."],tips:["Learn the colors of the signs.","Look for signs at school.","Learn to recognize the emergency exit sign."],warnings:["Read the signs and do what they say!"],realCase:'A child saw an electrical danger sign on a door and kept away from it. The teacher said, "Well done!"',video:"media/videos/lesson_signs.mp4",game:{instruction:"What does the yellow triangle mean?",items:[{text:"Danger!",emoji:"⚠️",correct:!0},{text:"Go!",emoji:"🟢",correct:!1},{text:"Not allowed",emoji:"🚫",correct:!1},{text:"Be careful",emoji:"👀",correct:!0}]},activity:{prompt:"You see a green sign with a white arrow. What does it mean?",image:"media/images/activity_signs.png",options:[{text:"The safe way out",correct:!0,feedback:"Green means safety, and the arrow shows the emergency exit route."},{text:"Not allowed",correct:!1,feedback:"Not allowed is shown by a red circle with a line; green means safety, like the way out."},{text:"Danger",correct:!1,feedback:"Danger is a yellow triangle; a green sign means safety, like the way out."},{text:"Stop",correct:!1,feedback:"A green sign does not mean stop; green means safety, and the arrow shows the way out."}]},quiz:[{question:"What does a red circle with a line across it mean?",options:[{text:"Not allowed / do not do it",correct:!0,feedback:"The red circle with a line tells you not to do something."},{text:"Go, this way is safe to use",correct:!1,feedback:"A red circle with a line means do not do it; it never means go."},{text:"Danger: watch out around here",correct:!1,feedback:"Danger is shown by a yellow triangle; the red circle with a line means do not do it."}],explanation:"A red circle with a red line across it means: do not do this! A yellow triangle means danger, and green means safety."},{question:"What does a yellow triangle with a black picture mean?",options:[{text:"Danger: be careful",correct:!0,feedback:"A yellow triangle warns you: be careful, there is danger!"},{text:"Safety: the way out",correct:!1,feedback:"The way out is shown in green; a yellow triangle means be careful, there is danger."},{text:"Not allowed: do not do it",correct:!1,feedback:"Not allowed is shown by a red circle with a line; a yellow triangle means be careful, there is danger."}],explanation:"A yellow triangle with a black picture means: be careful, there is danger! A red circle with a line means not allowed, and green means safety."},{question:"What does a blue circle sign mean?",options:[{text:"An instruction: you must do it",correct:!0,feedback:"A blue circle gives an instruction: it tells you something you must do."},{text:"Safety: this is the way out",correct:!1,feedback:"The way out is a green sign; a blue circle is an instruction that you must do."},{text:"Not allowed: you must not do it",correct:!1,feedback:"Not allowed is a red circle with a line; a blue circle is an instruction that you must do."}],explanation:"A blue circle is an instruction: you must do it. A red circle with a line means not allowed, a yellow triangle means danger and green means safety."}]},{id:14,icon:"School",accent:"#0d9488",title:"Emergency drills at school",subtitle:"Being ready for emergencies",grades:"3-4",ages:"8-10",summary:"Emergency drills prepare us for events such as fires and earthquakes, so that we know what to do when it really happens.",blocks:[{heading:"Listen to your teacher",body:"Always listen to your teacher's instructions.",image:"media/images/listen_teacher.png"},{heading:"Leave in an orderly way",body:"Do not push anyone. Leave in an orderly way, one after another, and help the younger children.",image:"media/images/orderly_exit.png"},{heading:"The assembly point",body:"Stay at the assembly point and wait until your teacher calls out your name.",image:"media/images/assembly_wait.png"}],examples:["Listen to your teacher.","Leave in an orderly way.","Help your friends.","Stay at the assembly point."],tips:["Treat the drill like a real emergency.","Learn the ways out.","Talk with your friends about the escape plan."],warnings:["Do not treat the drill as a game! It is there to protect your life."],realCase:"One day a fire broke out at a school. The pupils got out calmly and safely, because they had practiced beforehand!",video:"media/videos/lesson_drill.mp4",game:{instruction:"What do we do during a drill?",items:[{text:"We listen to the teacher",emoji:"👂",correct:!0},{text:"We play games",emoji:"🎮",correct:!1},{text:"We leave in an orderly way",emoji:"🚶",correct:!0},{text:"We collect our things",emoji:"🎒",correct:!1}]},activity:{prompt:"In the middle of a lesson, the alarm bell rings. What will you do?",image:"media/images/activity_drill.png",options:[{text:"I leave everything and go out in an orderly way",correct:!0,feedback:"When everyone leaves in an orderly way, without pushing, everyone gets out safely."},{text:"I collect my things",correct:!1,feedback:"Your things can wait; leave everything and go out in an orderly way."},{text:"I stay in the classroom",correct:!1,feedback:"Treat every alarm like a real emergency; go out and wait at the assembly point."},{text:"I stay to see what happens",correct:!1,feedback:"The alarm says get out now, so do not wait; go to the assembly point."}]},quiz:[{question:"When the alarm bell rings, what is the first thing to do?",options:[{text:"Leave everything and get out",correct:!0,feedback:"Leaving everything behind gets you out quickly and safely."},{text:"Collect your bag and books first",correct:!1,feedback:"Collecting your things slows you down; leave everything and get out."},{text:"Stay in the classroom",correct:!1,feedback:"When the alarm rings, everyone goes to the assembly point, so nobody is left inside."}],explanation:"When the alarm rings, leave everything and get out in an orderly way, one after another. Then wait at the assembly point until your teacher calls your name."},{question:"You are at the assembly point. What do you do?",options:[{text:"Wait there until your name is called",correct:!0,feedback:"Waiting until your teacher calls your name lets the teacher know that everyone is out."},{text:"Go back into the classroom for your bag",correct:!1,feedback:"Do not go back into the classroom; stay at the assembly point until your teacher calls your name."},{text:"Walk home to tell your family",correct:!1,feedback:"If you leave, your teacher cannot find you; stay at the assembly point until your name is called."}],explanation:"Stay at the assembly point and wait until your teacher calls out your name."},{question:"How do we leave the building during a drill?",options:[{text:"One after another, without pushing",correct:!0,feedback:"Leaving in an orderly way, one after another and without pushing, gets everyone out safely."},{text:"As fast as we can, pushing past others",correct:!1,feedback:"Do not push anyone; leave in an orderly way, one after another."},{text:"All together, running to the door",correct:!1,feedback:"Running all together is not orderly; leave one after another and help the younger children."}],explanation:"Do not push anyone. Leave in an orderly way, one after another, and help the younger children."}]},{id:15,icon:"Award",accent:"#4f46e5",title:"Safety hero",subtitle:"Responsibility and helping others",grades:"5-6",ages:"10-12",summary:"A safety hero is responsible, helps other people and behaves well. A real hero does not put themselves in danger, and tells adults.",blocks:[{heading:"Responsibility",body:"A safety hero looks out for their own safety and their friends' safety, and is always alert.",image:"media/images/responsibility.png"},{heading:"Helping",body:"A safety hero helps younger children and anyone else who needs help.",image:"media/images/help_others.png"},{heading:"Teaching",body:"Teach your friends what you learn, too. That way, knowledge grows!",image:"media/images/teach_friends.png"}],examples:["Be responsible.","Help others.","Teach your friends.","Be a good example."],tips:["Learn new things.","If you see a danger, tell your teacher.","Be a good example for your friends."],warnings:["A hero does not put themselves in danger! Being a hero means helping wisely and telling adults."],realCase:"A sixth-grade pupil taught her friends the number 115 and the escape plan. Later, when a fire broke out at the school, all her friends got out safely!",video:"media/videos/lesson_hero.mp4",game:{instruction:"What is a safety hero like?",items:[{text:"Is responsible",emoji:"💪",correct:!0},{text:"Plays games during an emergency",emoji:"🎮",correct:!1},{text:"Helps others",emoji:"🤝",correct:!0},{text:"Hides",emoji:"🙈",correct:!1}]},activity:{prompt:"During a drill, a first-grade child is frightened. What will you do?",image:"media/images/activity_hero.png",options:[{text:"I hold his hand and calmly show him the way",correct:!0,feedback:"Calmly helping a younger child is what a safety hero does."},{text:"I leave him and run",correct:!1,feedback:"The little child needs help to get out; stay calm and show him the way."},{text:"I laugh at him",correct:!1,feedback:"A scared child needs kindness; hold his hand and calmly show him the way."},{text:"I do nothing",correct:!1,feedback:"A safety hero helps younger children; hold his hand and calmly show him the way."}]},quiz:[{question:"What does a safety hero do?",options:[{text:"Helps others, teaches friends and is responsible",correct:!0,feedback:"Helping, teaching and being responsible keep you and your friends safe."},{text:"Only looks after themselves and forgets about friends",correct:!1,feedback:"A safety hero also looks out for friends and helps younger children."},{text:"Does nothing and waits for others to help",correct:!1,feedback:"A safety hero is always alert: if they see a danger, they tell the teacher."}],explanation:"A safety hero is responsible, helps others and teaches friends. A real hero does not go into danger, but tells adults."},{question:"A safety hero sees a danger at school. What does the hero do?",options:[{text:"Tells the teacher right away",correct:!0,feedback:"Telling the teacher about a danger keeps everyone safe; that is what a safety hero does."},{text:"Goes close to have a look at it",correct:!1,feedback:"Going close can put you in danger; a safety hero tells the teacher."},{text:"Tries to fix it alone",correct:!1,feedback:"A hero does not put themselves in danger; tell the teacher instead."}],explanation:"If you see a danger, tell your teacher. A real hero does not put themselves in danger, and tells adults."},{question:"Is a real hero someone who goes into danger to help?",options:[{text:"No, a hero helps wisely and tells adults",correct:!0,feedback:"Being a hero means helping wisely and telling adults; a hero does not put themselves in danger."},{text:"Yes, a hero goes into danger to save others",correct:!1,feedback:"A hero does not put themselves in danger! Help wisely and tell adults."},{text:"Yes, if a friend needs help",correct:!1,feedback:"Even when a friend needs help, a hero does not go into danger; tell adults right away."}],explanation:"A hero does not put themselves in danger! Being a hero means helping wisely and telling adults."}]},{id:16,icon:"FlameKindling",accent:"#ea580c",title:"Types of fire",subtitle:"The NFPA system: Classes A, B, C, D and K",grades:"4-6",ages:"9-12",summary:"Not all fires are the same! In the NFPA system there are five classes of fire: A (solid materials), B (flammable liquids and gases), C (electrical equipment), D (metals) and K (cooking oil). Each class is put out in its own special way. If water gets onto hot, burning oil, the fire shoots up violently and spreads!",blocks:[{heading:"Class A: solid materials",body:"Wood, paper, cloth and plastic. This class of fire is very common in homes and schools. Adults put it out with water or with an ABC powder fire extinguisher.",image:"media/images/fire_class_a.png"},{heading:"Class B: flammable liquids and gases",body:"Gasoline, kerosene, paint thinner, alcohol and gas. Very dangerous! Never pour water on this kind of fire, because it will spread. Adults put out burning liquids with foam, CO₂ or ABC powder (for alcohol: CO₂, ABC powder or a special alcohol-resistant foam, because ordinary foam does not work on it). Gas is different: adults turn off the gas only if it is safe. A gas flame is not put out while gas is still coming out, because the gas can explode. If the gas cannot be stopped safely, everyone gets out and calls 115.",image:"media/images/fire_class_b.png"},{heading:"Class C: electrical equipment",body:"Computers, televisions, wires and electrical sockets. Do not pour water on this kind of fire, because electricity can kill! Adults first cut off the electricity, then put the fire out with CO₂ or ABC powder. Note: this lesson uses the letters of the American NFPA 10 system as the project reference; the official system for Duhok is not yet confirmed. The European system (EN 2) uses other letters: NFPA A = EN A; NFPA B (liquids) = EN B; NFPA B (gases) = EN C; NFPA C (live electrical equipment) has no EN class; NFPA D = EN D; NFPA K = EN F.",image:"media/images/fire_class_c.png"}],examples:["Class A = wood, paper and cloth.","Class B = gasoline, kerosene and gas.","Class C = electrical equipment; do not pour water on it.","Class D = metals, Class K = cooking oil; ABC powder is not for these."],tips:["It is a good idea to have an ABC powder fire extinguisher at home, and for adults to know how to use it.","If you see a fire, do not go near it to find out what is burning: get out and tell an adult.","Call 115 for any fire."],warnings:["Never pour water on a cooking oil fire (K) or an electrical fire (C)!"],realCase:"In a kitchen, oil in a frying pan caught fire. Someone poured water on it, and the fire shot up violently and spread! The right thing would have been for an adult to turn off the gas and put a lid on the pan to cut off the oxygen. This was a Class K fire.",video:"media/videos/lesson_fire_types.mp4",game:{instruction:"Which of these are correct? (NFPA system)",items:[{text:"Burning wood = Class A",emoji:"🪵",correct:!0},{text:"Burning gasoline = Class A",emoji:"🛢️",correct:!1},{text:"A burning electric cable = Class C",emoji:"⚡",correct:!0},{text:"Burning paper = Class B",emoji:"📄",correct:!1},{text:"Burning oil in a frying pan = Class K",emoji:"🍳",correct:!0}]},activity:{prompt:'You see a school computer catch fire, and the teacher calls out, "Bring some water!" What will you do?',image:"media/images/activity_fire_types.png",options:[{text:'I say, "Teacher, do not pour water on it! It is an electrical fire (Class C)." Then we get out and call 115.',correct:!0,feedback:"Electricity can kill, so water is not for an electrical fire; then everyone gets out and calls 115."},{text:"I bring water",correct:!1,feedback:"Water on an electrical fire (Class C) is dangerous, because electricity can kill; tell the teacher and get out."},{text:"I pour water on the computer",correct:!1,feedback:"Children do not put out fires, and water on a computer fire is dangerous; get out and call 115."},{text:"I run away and tell nobody",correct:!1,feedback:"Telling others keeps them safe too; warn the teacher, get out together and call 115."}]},quiz:[{question:"If gasoline catches fire, what will adults use?",options:[{text:"Water",correct:!1,feedback:"No! Water spreads a gasoline fire."},{text:"Foam or CO₂",correct:!0,feedback:"Correct! Foam or CO₂ is good for burning liquids such as gasoline (Class B)."},{text:"They fan it with a piece of paper",correct:!1,feedback:"No! Air makes the fire bigger."}]},{question:"Which fire extinguisher is good for all three classes, A, B and C?",options:[{text:"A water extinguisher",correct:!1,feedback:"No, water is only for Class A."},{text:"An ABC powder extinguisher",correct:!0,feedback:"Correct! ABC powder is for A, B and C, but not for D and K."},{text:"There is no such extinguisher",correct:!1,feedback:"No, there is one: the ABC powder extinguisher."}]},{question:"You see a fire. Should you go closer to see what is burning?",options:[{text:"No, I get out and tell an adult",correct:!0,feedback:"Do not go near a fire to find out what is burning: get out, tell an adult and call 115."},{text:"Yes, so I can find out its class letter",correct:!1,feedback:"Do not go near a fire to find out what is burning; get out, tell an adult and call 115."},{text:"Yes, but only for a moment",correct:!1,feedback:"Even for a moment, going near a fire is not safe; get out and tell an adult."}],explanation:"If you see a fire, do not go near it to find out what is burning: get out and tell an adult. Call 115 for any fire."}]},{id:17,icon:"Siren",accent:"#dc2626",title:"Civil Defense heroes",subtitle:"The work and equipment of the 115 team",grades:"5-6",ages:"10-12",summary:"Civil Defense is a government organization that protects people's lives and property. Its teams come out for fires, earthquakes, floods and any other disaster. In Duhok, its teams are ready day and night.",blocks:[{heading:"What they do",body:"Putting out fires, rescuing people who are trapped, helping during disasters and teaching people about safety.",image:"media/images/cd_work.png"},{heading:"Their equipment",body:"Red fire engines, long water hoses, tall ladders, breathing apparatus (BA) and fire-resistant clothing.",image:"media/images/cd_equipment.png"},{heading:"How to call 115",body:`If there is an adult with you, tell them. If not, call 115 and say:
1. Where you are (the address or a place near you)
2. What has happened
3. How many people are injured
4. Your name

Do not hang up until they tell you to.`,image:"media/images/cd_call.png"}],examples:["A red fire engine with its siren on = the 115 team is coming.","A tall ladder = helps firefighters reach high windows.","Breathing apparatus = clean air to breathe inside the smoke.","Fire-resistant suit = protects the body from the heat of the fire."],tips:["Learn the number 115 by heart.","Know your home address.","When you hear a siren, move away from the road and let the red fire engine through."],warnings:["Calling 115 is not a game! If you call for no reason, someone else may be left without help."],realCase:"A fire broke out in a home in Duhok. A neighbor called 115. The 115 team came to the scene, put out the fire and brought the trapped people out safely.",video:"media/videos/lesson_cd_work.mp4",game:{instruction:"Which of these jobs does Civil Defense do?",items:[{text:"Putting out fires",emoji:"🔥",correct:!0},{text:"Selling pizza at the market",emoji:"🍕",correct:!1},{text:"Rescuing trapped people",emoji:"🆘",correct:!0},{text:"Presenting programs on television",emoji:"📺",correct:!1},{text:"Teaching pupils about safety",emoji:"🎓",correct:!0},{text:"Helping during floods",emoji:"🌊",correct:!0}]},activity:{prompt:"You are in the street and you see smoke coming out of the window of a house. There is nobody outside. What will you do?",image:"media/images/activity_cd_call.png",options:[{text:"I move away from the house, tell an adult or call 115 myself, and give the address of the place",correct:!0,feedback:"Moving away keeps you safe, and giving the address helps the 115 team get there quickly."},{text:"I go into the house to rescue the people",correct:!1,feedback:"Rescue is the job of the 115 team with their equipment; a real hero does not go into danger."},{text:"I run away and tell nobody",correct:!1,feedback:"People inside may need help, so tell an adult or call 115 and give the address."},{text:"I stay near the house and watch",correct:!1,feedback:"Staying near a burning house is not safe, and watching does not bring help; move away and call 115."}]},quiz:[{question:"What is the Civil Defense number?",options:[{text:"122",correct:!1,feedback:"No, 122 is the ambulance number."},{text:"115",correct:!0,feedback:"Correct! 115 is the Civil Defense number."},{text:"104",correct:!1,feedback:"No, 104 is the police number."}]},{question:"When you hear the siren of a red fire engine, what will you do?",options:[{text:"I run into the middle of the street",correct:!1,feedback:"That is not safe!"},{text:"I move away from the road and let it pass",correct:!0,feedback:"Correct! Make way for the Civil Defense vehicle."},{text:"I run after the fire engine to see where it goes",correct:!1,feedback:"That is not safe! A car could hit you."}]},{question:"People are trapped in a burning house. Who goes in to rescue them?",options:[{text:"The 115 team, with its equipment",correct:!0,feedback:"Rescue is the job of the 115 team with their equipment, such as breathing apparatus and fire-resistant clothing."},{text:"A child who wants to be a real hero",correct:!1,feedback:"A real hero does not go into danger; move away and tell an adult or call 115."},{text:"One of the neighbors",correct:!1,feedback:"Neighbors help by calling 115; rescuing trapped people is the job of the 115 team with their equipment."}],explanation:"Rescuing trapped people is the job of the 115 team, with breathing apparatus and fire-resistant clothing. A real hero does not go into danger: move away and tell an adult or call 115."}]},{id:18,icon:"ShieldAlert",accent:"#c2410c",title:"Dangerous objects: mines and unexploded ordnance",subtitle:"Do not touch, move away, tell an adult",grades:"1-6",ages:"6-12",summary:"After a war, some strange objects can stay in the ground for many years. Some of them can explode, even if they look old or rusty. A few easy rules keep you and your friends safe.",blocks:[{heading:"Strange objects can explode",body:"Mines and other explosive objects can be big or small. They can be any shape or color. Some look like toys, tins or old pieces of metal. They can hide in grass, in the soil or in old buildings. You cannot tell by looking if one is safe."},{heading:"The safe rules",body:`• Do not touch it, kick it or pick it up.
• Do not throw stones at it.
• Do not go closer to look.
• Move away and keep your friends away too.
• Tell an adult right away.`},{heading:"Signs and dangerous places",body:"Red signs, fences, tape or red stones show a dangerous place. Never go past them, and never take a sign away. A place with no sign can be dangerous too. Walk and play only where people walk and play every day."},{heading:"If you think you are in a dangerous place",body:"Stop. Stand very still. Shout for help. Wait for an adult or a rescuer to come. Do not run and do not walk back."}],examples:["A strange metal object in the grass = do not touch it, tell an adult.","A red sign with a skull = danger, do not go in.","A toy-like object in a field = leave it and tell an adult.","Adults call 115 = the Civil Defense number."],tips:["Walk on roads and paths that people use every day.","Tell an adult about every strange object you see.","Remind your friends of the safe rules."],warnings:["Never touch, kick, pick up or throw stones at a strange object!"],realCase:'On the way home from school, a girl saw a strange metal object next to the road. She did not go closer. She told her friends to stay back, and they walked home on the road. She told her mother, and her mother called 115. Her mother said, "You did the right thing!"',game:{instruction:"You see a strange object. Which are safe things to do?",items:[{text:"Tell an adult",emoji:"🗣️",correct:!0},{text:"Kick it",emoji:"🦶",correct:!1},{text:"Move away",emoji:"🚶",correct:!0},{text:"Pick it up",emoji:"✋",correct:!1},{text:"Keep friends away",emoji:"👫",correct:!0},{text:"Throw stones at it",emoji:"🪨",correct:!1}]},activity:{prompt:"You and your friend find a strange metal object near the playground. Your friend wants to pick it up. What do you do?",options:[{text:'I say "Stop, do not touch it!", we move away and I tell an adult',correct:!0,feedback:"Strange objects can explode. Moving away together and telling an adult keeps you both safe."},{text:"We look at it closely to see what it is",correct:!1,feedback:"Going closer is dangerous. Move away and tell an adult."},{text:"We throw small stones at it from far away",correct:!1,feedback:"Throwing anything at it can make it explode. Move away and tell an adult."},{text:"We take it home to show our family",correct:!1,feedback:"Never carry a strange object: it can explode. Leave it where it is and tell an adult."}]},quiz:[{question:"What do you do if you see a strange object on the ground?",options:[{text:"I move away and tell an adult",correct:!0},{text:"I pick it up and take it to show my teacher",correct:!1},{text:"I kick it so it goes far away",correct:!1}],explanation:"Strange objects can explode. Do not touch or kick them: move away and tell an adult right away."},{question:"What does a red sign with a skull mean?",options:[{text:"Danger: do not go past it",correct:!0},{text:"A good place to play hide and seek",correct:!1},{text:"A short way home",correct:!1}],explanation:"A red sign with a skull warns of danger. Never go past it and never take it away."},{question:"You think you are in a dangerous place. What do you do?",options:[{text:"I stop, stand still, shout for help and wait",correct:!0},{text:"I run out of the place as fast as I can",correct:!1},{text:"I walk back carefully in my own footprints to the road",correct:!1}],explanation:"When you stand still, you do not step on another dangerous object. Shout for help and wait for an adult or a rescuer."}]},{id:19,icon:"LifeBuoy",accent:"#0284c7",title:"Water safety",subtitle:"Swimming and playing near water",grades:"1-6",ages:"6-12",summary:"Swimming and playing in water are fun, but water can be dangerous. Rivers, dams, canals, ponds and pools can be deep, cold or fast. Drowning can happen quickly and quietly, so always stay with an adult who is watching you.",blocks:[{heading:"Water can be dangerous",body:"Rivers, dams, canals, ponds and pools can be deep. The water can be cold and fast, even when it looks calm. You cannot see the bottom or what is hidden under the water."},{heading:"Always with an adult who is watching",body:"Ask an adult before you go near water. Swim and play in water only when an adult is with you and watching you all the time. Never swim alone, even if you swim well."},{heading:"Before you go in",body:"Wear a life jacket that fits you near rivers, lakes and dams and in a boat. Never jump into water when you do not know how deep it is: rocks or shallow places may be hidden under the water."},{heading:"If someone is in trouble in the water",body:`Do not go into the water. Shout loudly for an adult. Throw something that floats, like a ball or a life ring, and stay back from the edge. If no adult is near, call 115.

A child never goes into the water to rescue someone.`}],examples:["A calm river can still be deep, cold and fast.","An adult watches you all the time when you swim.","A life jacket that fits you helps you float.","Someone in trouble in the water: shout for an adult and throw something that floats."],tips:["Always ask an adult before you go near water.","Never swim alone.","Learn to swim with a trained teacher. Even good swimmers need an adult watching them."],warnings:["Never go into the water to rescue someone! Shout for an adult and throw something that floats."],realCase:"On a hot summer day, two friends were near a canal. One of them wanted to jump into the water to cool down. The other friend said no: they did not know how deep the water was, and no adult was with them. They went home and told their parents. Later, they swam at a pool, with an adult watching them all the time.",game:{instruction:"Which of these are safe near water? Choose the correct ones:",items:[{text:"Ask an adult before going near water",emoji:"🙋",correct:!0},{text:"Swim alone in a river",emoji:"🌊",correct:!1},{text:"Wear a life jacket that fits you",emoji:"🦺",correct:!0},{text:"Jump into water when you do not know how deep it is",emoji:"🤸",correct:!1},{text:"Shout for an adult and throw something that floats",emoji:"📣",correct:!0},{text:"Go into the water to rescue a friend",emoji:"🏊",correct:!1}]},activity:{prompt:"You are playing near a pond with a friend. Your friend slips and falls into the deep water. What will you do?",options:[{text:"I stay out of the water, shout loudly for an adult and throw something that floats",correct:!0,feedback:"A child never goes into the water to rescue someone. Shouting brings an adult, and something that floats helps your friend stay up."},{text:"I jump into the water and pull my friend out",correct:!1,feedback:"If you go into the water, you can drown too. Stay out, shout for an adult and throw something that floats."},{text:"I lean over the edge and grab my friend's hand",correct:!1,feedback:"You can slip or be pulled into the water too. Stay back from the edge, shout for an adult and throw something that floats."},{text:"I run home and tell nobody because I am scared",correct:!1,feedback:"Your friend needs help fast. Shout for an adult right away; if no adult is near, call 115."}]},quiz:[{question:"Who must be with you when you swim or play near water?",options:[{text:"An adult who is watching you all the time",correct:!0},{text:"A friend of your age who can swim well",correct:!1},{text:"Nobody, if you already know how to swim well",correct:!1}],explanation:"Drowning can happen quickly and quietly. An adult must be close to you and watching you all the time, even if you can swim."},{question:"Your friend is in trouble in the water. What do you do?",options:[{text:"Stay out, shout for an adult and throw something that floats",correct:!0},{text:"Jump in quickly and pull your friend to the side of the water",correct:!1},{text:"Wait quietly at the edge until your friend climbs out alone",correct:!1}],explanation:"A child never goes into the water to rescue someone. Shouting brings an adult, and something that floats helps your friend stay up."},{question:"You want to jump into a river, but you do not know how deep it is. What is right?",options:[{text:"Do not jump: rocks or shallow places may be hidden under the water",correct:!0},{text:"Jump in, because older children are already jumping into the water there",correct:!1},{text:"Dive in head first so that you get into the deep water quickly",correct:!1}],explanation:"You cannot see what is under the water. A hidden rock or a shallow place can cause a very serious injury. Never jump into water when you do not know how deep it is."}]}],t={lessons:e};export{t as default,e as lessons};
